      en: ["Founded c. 102 AD", "Roman town planning", "Agora and city gates", "Archaeological monument"],
      es: ["Fundada hacia 102 d.C.", "Urbanismo romano", "Ágora y puertas de la ciudad", "Monumento arqueológico"],
      pt: ["Fundada cerca de 102 d.C.", "Urbanismo romano", "Ágora e portões da cidade", "Monumento arqueológico"],
